package app.yoru.mobile;

import android.app.*;
import android.view.*;
import android.widget.*;
import androidx.recyclerview.widget.*;
import org.json.*;
import java.text.*;
import java.util.*;
import java.util.concurrent.*;

public final class CalendarScreen extends LinearLayout {
    private static final int DAYS=21;
    private static final String[][] FILTERS={{"all","Все"},{"fav","Избранное"},{"new","Новые"},{"soon","Скоро"},{"premiere","Премьеры"},{"ongoing","Выходит"},{"film","Фильмы"}};
    private final Activity activity;private final LinearLayout dayRow,filterRow;private final RecyclerView recycler;private final AiringAdapter adapter;private final TextView state,heroTitle,heroMeta;private final ArrayList<ApiRepository.AiringItem> items=new ArrayList<>();private final HashMap<String,ArrayList<ArrayList<ApiRepository.AiringItem>>> buckets=new HashMap<>();private final Locale ru=new Locale("ru");private final long[] starts=new long[DAYS];private final String[] shortDays=new String[DAYS],longDays=new String[DAYS];private int selected,generation;private String filter="all";private boolean attached=true;private Future<?> loadFuture;
    public CalendarScreen(Activity a){super(a);activity=a;setOrientation(VERTICAL);setPadding(Ui.dp(a,18),Ui.dp(a,14),Ui.dp(a,18),0);prepareDays();addView(Ui.label(a,"КАЛЕНДАРЬ YORU"));Ui.space(this,11);addView(Ui.text(a,"Выход серий",29,Ui.TEXT,true));Ui.space(this,9);addView(Ui.text(a,"Онгоинги, премьеры и ближайшие серии с точными датами выхода, когда они доступны.",12,Ui.MUTED,false));Ui.space(this,17);LinearLayout hero=Ui.column(a);hero.setPadding(Ui.dp(a,18),Ui.dp(a,18),Ui.dp(a,18),Ui.dp(a,18));hero.setBackground(Ui.gradient(0xff2e2140,0xff181220,20,a));heroTitle=Ui.text(a,"Открываем календарь…",21,Ui.TEXT,true);hero.addView(heroTitle);Ui.space(hero,8);heroMeta=Ui.text(a,"YORU готовит быстрые фильтры",12,0xffd8c7ea,false);hero.addView(heroMeta);Ui.space(hero,13);hero.addView(Ui.button(a,"Обновить календарь",false,this::load));addView(hero,Ui.lp(a,-1,-2));Ui.space(this,17);HorizontalScrollView days=new HorizontalScrollView(a);days.setHorizontalScrollBarEnabled(false);dayRow=Ui.row(a);days.addView(dayRow);addView(days,Ui.lp(a,-1,-2));Ui.space(this,10);HorizontalScrollView filters=new HorizontalScrollView(a);filters.setHorizontalScrollBarEnabled(false);filterRow=Ui.row(a);filters.addView(filterRow);addView(filters,Ui.lp(a,-1,-2));Ui.space(this,12);state=Ui.text(a,"",12,Ui.MUTED,false);addView(state);Ui.space(this,10);recycler=new RecyclerView(a);recycler.setLayoutManager(new LinearLayoutManager(a));recycler.setHasFixedSize(false);recycler.setItemViewCacheSize(14);recycler.setClipToPadding(false);recycler.setPadding(0,0,0,Ui.dp(a,26));adapter=new AiringAdapter();recycler.setAdapter(adapter);addView(recycler,new LinearLayout.LayoutParams(-1,0,1));load();}
    @Override protected void onAttachedToWindow(){super.onAttachedToWindow();attached=true;}
    @Override protected void onDetachedFromWindow(){attached=false;if(loadFuture!=null)loadFuture.cancel(true);super.onDetachedFromWindow();}
    private void load(){int gen=++generation;if(loadFuture!=null)loadFuture.cancel(true);prepareDays();ArrayList<ApiRepository.AiringItem> cached=ApiRepository.airingFromJson(YoruApp.app().cache.schedule(3*60*60*1000L));if(cached.isEmpty())cached=ApiRepository.airingFromJson(readLegacyCache());if(!cached.isEmpty()){setItems(cached);state.setText("Календарь открыт сразу · обновляем даты");}else{state.setText("Обновляем календарь…");heroTitle.setText("YORU следит за неделей");heroMeta.setText("Даты появятся сразу после ответа расписания.");adapter.loading();renderFilters();renderDays();}loadFuture=YoruApp.app().ui.submit(()->{try{ArrayList<ApiRepository.AiringItem> loaded=YoruApp.app().api.airingSchedule(DAYS,YoruApp.app().store.favorites());JSONArray json=ApiRepository.airingJson(loaded);YoruApp.app().cache.schedule(json);YoruApp.app().store.calendarCache(json);YoruApp.app().calendarTodayCount=ApiRepository.todayCount(loaded);YoruApp.app().main.post(()->{if(!alive()||gen!=generation)return;setItems(loaded);});}catch(Exception e){YoruApp.app().main.post(()->{if(!alive()||gen!=generation)return;if(items.isEmpty()){if(!cached.isEmpty()){setItems(cached);state.setText("Показан сохранённый календарь. Свежие даты пока не ответили.");}else{state.setText("Календарь временно недоступен");adapter.empty("Календарь временно недоступен","YORU продолжает работать. Нажмите “Обновить календарь”, когда сеть стабилизируется.");}}else state.setText("Сохранённый календарь открыт · свежие даты пока недоступны");});}});}
    public void quickShow(){prepareDays();if(items.isEmpty()){ArrayList<ApiRepository.AiringItem> cached=ApiRepository.airingFromJson(YoruApp.app().cache.schedule(3*60*60*1000L));if(cached.isEmpty())cached=ApiRepository.airingFromJson(readLegacyCache());if(!cached.isEmpty())setItems(cached);else{renderFilters();renderDays();}}}
    private JSONArray readLegacyCache(){try{return new JSONArray(YoruApp.app().store.calendarCache());}catch(Exception e){return new JSONArray();}}
    private boolean alive(){return attached&&!activity.isFinishing();}
    private void setItems(List<ApiRepository.AiringItem> rows){items.clear();if(rows!=null)items.addAll(rows);buildBuckets();if(dayItems(selected).isEmpty())selected=firstDayWithEvents();renderFilters();renderDays();renderList();}
    private void buildBuckets(){buckets.clear();for(String[] f:FILTERS){ArrayList<ArrayList<ApiRepository.AiringItem>> days=new ArrayList<>(DAYS);for(int i=0;i<DAYS;i++)days.add(new ArrayList<>());buckets.put(f[0],days);}long now=System.currentTimeMillis();for(ApiRepository.AiringItem item:items){if(item==null||item.anime==null)continue;int day=(int)((startOfDay(item.time)-starts[0])/(24L*60*60*1000));if(day<0||day>=DAYS)continue;boolean fav=YoruApp.app().store.favorite(item.anime);boolean history=YoruApp.app().store.progress(item.anime).length()>0;boolean premiere="Премьера".equals(item.kind);boolean ongoing=item.anime.ongoing()||"Новая серия".equals(item.kind);boolean film=item.anime.type.toLowerCase(Locale.ROOT).contains("фильм");addBucket("all",day,item);if(fav)addBucket("fav",day,item);if(!history&&!fav)addBucket("new",day,item);if(item.time>=now)addBucket("soon",day,item);if(premiere)addBucket("premiere",day,item);if(ongoing)addBucket("ongoing",day,item);if(film)addBucket("film",day,item);}}
    private void addBucket(String key,int day,ApiRepository.AiringItem item){ArrayList<ArrayList<ApiRepository.AiringItem>> days=buckets.get(key);if(days!=null&&day>=0&&day<days.size())days.get(day).add(item);}
    private ArrayList<ApiRepository.AiringItem> dayItems(int day){ArrayList<ArrayList<ApiRepository.AiringItem>> days=buckets.get(filter);if(days==null||day<0||day>=days.size())return new ArrayList<>();return days.get(day);}
    private void renderDays(){dayRow.removeAllViews();for(int i=0;i<DAYS;i++){final int index=i;TextView chip=Ui.chip(activity,shortDays[i]+" · "+dayItems(i).size(),i==selected,()->{if(selected==index)return;selected=index;renderDays();renderList();});LinearLayout.LayoutParams p=Ui.lp(activity,-2,-2);p.rightMargin=Ui.dp(activity,7);dayRow.addView(chip,p);}}
    private void renderFilters(){filterRow.removeAllViews();for(String[] r:FILTERS){TextView chip=Ui.chip(activity,r[1],r[0].equals(filter),()->{if(r[0].equals(filter))return;filter=r[0];selected=firstDayWithEvents();renderFilters();renderDays();renderList();});LinearLayout.LayoutParams p=Ui.lp(activity,-2,-2);p.rightMargin=Ui.dp(activity,7);filterRow.addView(chip,p);}}
    private void renderList(){ArrayList<ApiRepository.AiringItem> day=dayItems(selected);String title=day.isEmpty()?"На этот день пока пусто":nearestTitle();int filtered=filteredCount();heroTitle.setText(title);heroMeta.setText(items.isEmpty()?"Нет данных календаря":filtered+" событий по текущему фильтру · "+exactCount()+" с точным временем");state.setText(longDays[selected]+(day.isEmpty()?" · новых серий не найдено":" · событий: "+day.size()));if(day.isEmpty())emptyForFilter();else adapter.rows(day);}
    private View itemCard(ApiRepository.AiringItem item){LinearLayout card=Ui.row(activity);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(Ui.dp(activity,12),Ui.dp(activity,12),Ui.dp(activity,12),Ui.dp(activity,12));card.setBackground(Ui.stroke(Ui.CARD,16,activity));ImageView poster=new ImageView(activity);poster.setScaleType(ImageView.ScaleType.CENTER_CROP);poster.setBackground(Ui.shape(Ui.SURFACE,12,activity));poster.setClipToOutline(true);card.addView(poster,Ui.lp(activity,54,76));if(item.anime!=null)YoruApp.app().images.load(poster,item.anime);LinearLayout text=Ui.column(activity);text.setPadding(Ui.dp(activity,12),0,0,0);TextView name=Ui.text(activity,item.anime==null?"Аниме":item.anime.title,14,Ui.TEXT,true);name.setMaxLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);text.addView(name);Ui.space(text,6);text.addView(Ui.text(activity,item.kind+" · серия "+item.episode+" · "+time(item.time),11,Ui.PURPLE,true));Ui.space(text,5);text.addView(Ui.text(activity,countdown(item.time)+" · "+item.precision,10,Ui.MUTED,false));card.addView(text,new LinearLayout.LayoutParams(0,-2,1));Ui.Icon icon=new Ui.Icon(activity,"play");icon.color=Ui.PURPLE;card.addView(icon,Ui.lp(activity,24,24));Ui.press(card);card.setOnClickListener(v->{if(item.anime!=null)Ui.openDetails(activity,item.anime);});return card;}
    private View progressCard(){LinearLayout c=Ui.column(activity);c.setPadding(Ui.dp(activity,16),Ui.dp(activity,18),Ui.dp(activity,16),Ui.dp(activity,18));c.setGravity(Gravity.CENTER_HORIZONTAL);c.setBackground(Ui.stroke(Ui.CARD,16,activity));ProgressBar bar=new ProgressBar(activity);c.addView(bar,Ui.lp(activity,36,36));Ui.space(c,12);c.addView(Ui.text(activity,"Собираем ближайшие релизы…",12,Ui.MUTED,true));return c;}
    private View emptyCard(String title,String message){LinearLayout c=Ui.column(activity);c.setPadding(Ui.dp(activity,16),Ui.dp(activity,18),Ui.dp(activity,16),Ui.dp(activity,18));c.setBackground(Ui.stroke(Ui.CARD,16,activity));c.addView(Ui.text(activity,title,17,Ui.TEXT,true));Ui.space(c,8);c.addView(Ui.text(activity,message,12,Ui.MUTED,false));return c;}
    private int firstDayWithEvents(){for(int i=0;i<DAYS;i++)if(!dayItems(i).isEmpty())return i;return Math.max(0,Math.min(DAYS-1,selected));}
    private int filteredCount(){int n=0;ArrayList<ArrayList<ApiRepository.AiringItem>> days=buckets.get(filter);if(days!=null)for(ArrayList<ApiRepository.AiringItem> d:days)n+=d.size();return n;}
    private int exactCount(){int n=0;ArrayList<ArrayList<ApiRepository.AiringItem>> days=buckets.get(filter);if(days!=null)for(ArrayList<ApiRepository.AiringItem> d:days)for(ApiRepository.AiringItem item:d)if("Точная дата".equals(item.precision)||"Премьера".equals(item.precision))n++;return n;}
    private String nearestTitle(){long now=System.currentTimeMillis();ApiRepository.AiringItem best=null,past=null;ArrayList<ArrayList<ApiRepository.AiringItem>> days=buckets.get(filter);if(days!=null)for(ArrayList<ApiRepository.AiringItem> d:days)for(ApiRepository.AiringItem item:d){if(item.time>=now&&(best==null||item.time<best.time))best=item;if(item.time<now&&(past==null||item.time>past.time))past=item;}if(best==null)best=past;return best==null?"Календарь YORU":(best.time<System.currentTimeMillis()?"Уже вышло: ":"Ближайшая серия: ")+(best.anime==null?"аниме":best.anime.title);}
    private void emptyForFilter(){if("fav".equals(filter)){int fav=YoruApp.app().store.favoriteCount();adapter.empty(fav>0?"В избранном пока нет дат":"Избранное пустое",fav>0?"YORU проверяет избранные тайтлы через расписание Shikimori. Если точной даты ещё нет у расписания, она появится после обновления.":"Добавьте онгоинг в коллекцию, и календарь будет показывать дату новой серии здесь.");return;}adapter.empty("Тихий день","Проверьте соседние дни или обновите календарь. У части онгоингов дата может появиться ближе к релизу.");}
    private void prepareDays(){long base=todayStart();for(int i=0;i<DAYS;i++){starts[i]=base+i*24L*60*60*1000;shortDays[i]=i==0?"Сегодня":i==1?"Завтра":new SimpleDateFormat("EEE dd.MM",ru).format(new Date(starts[i])).replaceFirst("\\.","");longDays[i]=i==0?"Сегодня":i==1?"Завтра":new SimpleDateFormat("EEEE, dd MMMM",ru).format(new Date(starts[i]));}}
    private long todayStart(){Calendar c=Calendar.getInstance();c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c.getTimeInMillis();}
    private long startOfDay(long t){Calendar c=Calendar.getInstance();c.setTimeInMillis(t);c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);c.set(Calendar.MILLISECOND,0);return c.getTimeInMillis();}
    private String time(long t){return new SimpleDateFormat("HH:mm",ru).format(new Date(t));}
    private String countdown(long t){long diff=t-System.currentTimeMillis();if(diff<=-90*60*1000)return "уже вышло";if(diff<=0)return "выходит сейчас";long min=diff/60000,h=min/60,d=h/24;if(d>0)return "через "+d+" д "+(h%24)+" ч";if(h>0)return "через "+h+" ч "+(min%60)+" мин";return "через "+Math.max(1,min)+" мин";}
    private final class AiringAdapter extends RecyclerView.Adapter<AiringHolder>{private final ArrayList<ApiRepository.AiringItem> rows=new ArrayList<>();private boolean loading;private String emptyTitle="",emptyText="";void rows(List<ApiRepository.AiringItem> next){loading=false;emptyTitle="";rows.clear();if(next!=null)rows.addAll(next);notifyDataSetChanged();recycler.scrollToPosition(0);}void empty(String title,String text){loading=false;rows.clear();emptyTitle=title;emptyText=text;notifyDataSetChanged();}void loading(){loading=true;rows.clear();emptyTitle="";notifyDataSetChanged();}public int getItemCount(){return rows.isEmpty()?1:rows.size();}public int getItemViewType(int p){return loading?2:rows.isEmpty()?1:0;}public AiringHolder onCreateViewHolder(ViewGroup parent,int viewType){FrameLayout box=new FrameLayout(activity);box.setPadding(0,0,0,Ui.dp(activity,9));box.setLayoutParams(new RecyclerView.LayoutParams(-1,-2));return new AiringHolder(box);}public void onBindViewHolder(AiringHolder h,int p){h.box.removeAllViews();View v=loading?progressCard():rows.isEmpty()?emptyCard(emptyTitle,emptyText):itemCard(rows.get(p));h.box.addView(v,new FrameLayout.LayoutParams(-1,-2));}}
    private static final class AiringHolder extends RecyclerView.ViewHolder{final FrameLayout box;AiringHolder(FrameLayout v){super(v);box=v;}}
}
